package com.lqq.supportflow.knowledge.infrastructure.search;
import com.lqq.supportflow.knowledge.domain.*; import java.time.Duration; import java.util.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.stereotype.Component; import org.springframework.web.reactive.function.client.WebClient;
@Component @ConditionalOnProperty(prefix="supportflow.search.elasticsearch",name="enabled",havingValue="true") public class ElasticsearchKnowledgeSearchIndex implements KnowledgeSearchIndex { private final WebClient client; private final String index; public ElasticsearchKnowledgeSearchIndex(WebClient.Builder builder,@Value("${supportflow.search.elasticsearch.endpoint}") String endpoint,@Value("${supportflow.search.elasticsearch.index:supportflow-knowledge}") String index){this.client=builder.baseUrl(endpoint).build();this.index=index;} public void index(Long tenantId,Long knowledgeBaseId,Long documentId,List<IndexedKnowledgeChunk> entries){for(IndexedKnowledgeChunk entry:entries){KnowledgeChunk chunk=entry.chunk();List<Float> vector=new ArrayList<>();for(float value:entry.embedding())vector.add(value);Map<String,Object> document=Map.of("tenantId",tenantId,"knowledgeBaseId",knowledgeBaseId,"documentId",documentId,"chunkId",chunk.id(),"chunkNo",chunk.chunkNo(),"content",chunk.content(),"embedding",vector);client.put().uri("/"+index+"/_doc/"+chunk.id()).bodyValue(document).retrieve().toBodilessEntity().block(Duration.ofSeconds(15));}}}
